import functools

import jax
import jax.numpy as jnp
from jax import lax
from jax.experimental import pallas as pl
from jax.experimental.pallas import tpu as pltpu

BLOCK = 128  # fp8 quantization block (block x block); inferred from scale shapes below


def _pick(dim, prefs):
    for t in prefs:
        if dim % t == 0:
            return t
    return dim


def _kernel(a_ref, as_ref, w_ref, ws_ref, o_ref, a_scr, w_scr, acc_ref, *, tm, tn, nk, b):
    j = pl.program_id(1)
    k = pl.program_id(2)

    # Dequantize the A row-panel once (first N tile) into the resident bf16 scratch.
    @pl.when(j == 0)
    def _fill_a():
        for rb in range(tm // b):
            rows = slice(rb * b, (rb + 1) * b)
            blk = a_ref[rows, :].astype(jnp.float32)          # (b, tk)
            s = as_ref[rb]                                     # (1, tk) f32
            a_scr[k, rows, :] = (blk * s).astype(jnp.bfloat16)

    # Dequantize this W tile (each W element exactly once overall).
    for rb in range(tn // b):
        rows = slice(rb * b, (rb + 1) * b)
        blk = w_ref[rows, :].astype(jnp.float32)              # (b, tk)
        s = ws_ref[rb]                                         # (1, tk) f32
        w_scr[rows, :] = (blk * s).astype(jnp.bfloat16)

    @pl.when(k == 0)
    def _zero():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += lax.dot_general(
        a_scr[k], w_scr[...], (((1,), (1,)), ((), ())),
        preferred_element_type=jnp.float32,
    )

    @pl.when(k == nk - 1)
    def _store():
        o_ref[...] = acc_ref[...].astype(o_ref.dtype)


def workload(a_q, a_s, w_q, w_s):
    M, K = a_q.shape
    N, _ = w_q.shape
    b = M // a_s.shape[0]  # quantization block size

    tk = _pick(K, (1024, 512, 256, 128))
    tn = _pick(N, (512, 256, 128))
    if M * K * 2 <= 40 * 1024 * 1024:
        tm = M
    else:
        tm = _pick(M, (2048, 1024, 512, 256, 128))
    nk = K // tk

    # Lane-expand the per-block scales: (rows/b, K/b) -> (rows/b, 1, K)  (layout ops only)
    a_se = jnp.broadcast_to(a_s[:, :, None], (M // b, K // b, b)).reshape(M // b, 1, K)
    w_se = jnp.broadcast_to(w_s[:, :, None], (N // b, K // b, b)).reshape(N // b, 1, K)

    def a_map(i, j, k):
        kk = k * (1 - jnp.minimum(j, 1))  # only fetch A panels during the first N tile
        return (i, kk)

    def as_map(i, j, k):
        kk = k * (1 - jnp.minimum(j, 1))
        return (i, 0, kk)

    kernel = functools.partial(_kernel, tm=tm, tn=tn, nk=nk, b=b)

    return pl.pallas_call(
        kernel,
        out_shape=jax.ShapeDtypeStruct((M, N), jnp.bfloat16),
        grid=(M // tm, N // tn, nk),
        in_specs=[
            pl.BlockSpec((tm, tk), a_map),
            pl.BlockSpec((tm // b, 1, tk), as_map),
            pl.BlockSpec((tn, tk), lambda i, j, k: (j, k)),
            pl.BlockSpec((tn // b, 1, tk), lambda i, j, k: (j, 0, k)),
        ],
        out_specs=pl.BlockSpec((tm, tn), lambda i, j, k: (i, j)),
        scratch_shapes=[
            pltpu.VMEM((nk, tm, tk), jnp.bfloat16),   # dequantized A panel (resident)
            pltpu.VMEM((tn, tk), jnp.bfloat16),       # dequantized W tile
            pltpu.VMEM((tm, tn), jnp.float32),        # f32 accumulator
        ],
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("arbitrary", "arbitrary", "arbitrary"),
            vmem_limit_bytes=100 * 1024 * 1024,
        ),
    )(a_q, a_se, w_q, w_se)

