    hw = h * w
    if w % 128 == 0:
        r, l = h, w
        x4 = x
    elif hw % 128 == 0:
        r, l = hw // 128, 128
        x4 = x.reshape(n, c, r, l)
    else:
        r, l = h, w
        x4 = x
    g = gamma.astype(jnp.float32)
    b = beta.astype(jnp.float32)
    ch = _pick_chunk(r, l)
    kern = functools.partial(_bn_kernel, count=float(n * hw), eps=_EPS, ch=ch)
    out = pl.pallas_call(
        kern,
        out_shape=jax.ShapeDtypeStruct((n, c, r, l), x.dtype),
        grid=(c,),
        in_specs=[
            pl.BlockSpec(memory_space=pltpu.SMEM),
            pl.BlockSpec(memory_space=pltpu.SMEM),
            pl.BlockSpec((n, 1, r, l), lambda i: (0, i, 0, 0)),
        ],
        out_specs=pl.BlockSpec((n, 1, r, l), lambda i: (0, i, 0, 0)),
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel",),
            vmem_limit_bytes=64 * 1024 * 1024,
        ),
    )(g, b, x4)
    if (r, l) != (h, w):
        out = out.reshape(n, c, h, w)
